Voici un exemple de code C# qui crée un serveur HTTP en utilisant l'objet `System.Net.HttpListener` et écoute les requêtes sur le port 8080. Le serveur répondra avec le texte "Hello, World!" pour les requêtes GET vers la page "hello".
```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class HttpServer
{
    static readonly HttpListener _listener = new HttpListener();
    static readonly string _page = "hello";

    static void Main(string[] args)
    {
        _listener.Prefixes.Add("http://localhost:8080/");
        _listener.Start();

        Console.WriteLine("Server started. Listening on port 8080...");

        while (true)
        {
            HttpListenerContext context = _listener.GetContext();
            HandleRequest(context);
        }
    }

    static void HandleRequest(HttpListenerContext context)
    {
        HttpListenerRequest request = context.Request;
        HttpListenerResponse response = context.Response;

        if (request.Url.AbsolutePath == _page)
        {
            string responseText = "Hello, World!";
            byte[] buffer = Encoding.UTF8.GetBytes(responseText);
            response.ContentLength64 = buffer.Length;
            response.OutputStream.Write(buffer, 0, buffer.Length);
            response.OutputStream.Close();
        }
        else
        {
            string errorMessage = "Page not found";
            byte[] buffer = Encoding.UTF8.GetBytes(errorMessage);
            response.StatusCode = 404;
            response.ContentLength64 = buffer.Length;
            response.OutputStream.Write(buffer, 0, buffer.Length);
            response.OutputStream.Close();
        }
    }
}
```
