class PasswordGenerator {
  constructor() {
    this.characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+';
  }

  generatePassword(length) {
    if (length < 8 || length > 128) {
      throw new Error('La longitud de la contraseña debe ser entre 8 y 128 caracteres');
    }
    const password = '';
    for (let i = 0; i < length; i++) {
      password += this.characters.charAt(Math.floor(Math.random() * this.characters.length));
    }
    return password;
  }

  generateStrongPassword(length) {
    if (length < 12 || length > 128) {
      throw new Error('La longitud de la contraseña debe ser entre 12 y 128 caracteres');
    }
    const password = '';
    for (let i = 0; i < length; i++) {
      const charType = Math.floor(Math.random() * 4);
      switch (charType) {
        case 0: // Letra mayúscula
          password += this.characters.charAt(Math.floor(Math.random() * this.characters.length));
          break;
        case 1: // Letra minúscula
          password += this.characters.toLowerCase().charAt(Math.floor(Math.random() * this.characters.length));
          break;
        case 2: // Dígito
          password += '0123456789'.charAt(Math.floor(Math.random() * 10));
          break;
        case 3: // Caracter especial
          password += '!@#$%^&*()_+'.charAt(Math.floor(Math.random() * 10));
          break;
      }
    }
    return password;
  }
}
