// Функция для вычисления значения интеграла методом прямоугольников
double rectangleIntegration(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

// Функция для вычисления значения интеграла методом трапеций
double trapezoidIntegration(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.5 * (f(a) + f(b));
    for (int i = 1; i < n; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

// Функция для вычисления значения интеграла методом парабол (метод Симпсона)
double parabolicIntegration(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = f(a);
    for (int i = 1; i <= n / 2; i++) {
        sum += 2 * f(a + (2 * i - 1) * h);
    }
    sum += 4 * f(a + n * h);
    return sum * h / 3;
}

