            return 1;
        }
    }

    // ожидаем завершения вычислений всеми потоками
    for (int i = 0; i < numThreads; i++) {
        WaitForSingleObject(thread, INFINITE);
    }

    // вывод результатов вычислений
    for (int i = 0; i < numThreads; i++) {
        std::cout << "Thread " << i << ": " << results[i].load() << std::endl;
    }

    // освобождение мьютекса
    ReleaseMutex(mutex);
    return 0;
