```cpp
// Structura para un nodo del árbol binario
struct Node {
    int value;
    Node* left;
    Node* right;
};

// Función para insertar un nuevo nodo en el árbol binario
void insertNode(Node** root, int value) {
    if (*root == nullptr) {
        *root = new Node();
        (*root)->value = value;
        (*root)->left = nullptr;
        (*root)->right = nullptr;
    } else {
        if (value < (*root)->value) {
            insertNode(&((*root)->left), value);
        } else if (value > (*root)->value) {
            insertNode(&((*root)->right), value);
        }
    }
}

// Función para buscar un valor en el árbol binario
bool searchNode(Node* root, int value) {
    if (root == nullptr) {
        return false;
    }
    if (root->value == value) {
        return true;
    }
    if (value < root->value) {
        return searchNode(root->left, value);
    } else {
        return searchNode(root->right, value);
    }
}

int main() {
    Node* root = nullptr; // Raíz del árbol binario
    int values[] = {5, 2, 8, 3, 9, 1, 4, 6, 7};
    for (int i = 0; i < sizeof(values) / sizeof(int); i++) {
        insertNode(&root, values[i]);
    }

    int valueToSearch = 4;
    if (searchNode(root, valueToSearch)) {
        cout << valueToSearch << " found in the tree" << endl;
    } else {
        cout << valueToSearch << " not found in the tree" << endl;
    }

    return 0;
}
```
La función `insertNode` inserta un nuevo nodo en el árbol binario recursivamente, siguiendo la regla de búsqueda de Hastings (si el valor es menor que el valor del nodo actual, se busca en el nodo izquierdo; si es mayor, se busca en el nodo derecho).

La función `searchNode` busca un valor en el árbol binario recursivamente, también siguiendo la regla de búsqueda de Hastings. Si el nodo actual es `nullptr`, se devuelve `false`. Si el valor coincide con el valor del nodo actual, se devuelve `true`. Si el valor es menor que el valor del nodo actual, se sigue buscando en el nodo izquierdo; si es mayor, se sigue buscando en el nodo derecho.

